package com.cpgame.g2110.core;
import com.fasterxml.jackson.databind.*;import java.nio.file.*;import java.security.SecureRandom;import java.util.*;
public final class GenerationValidationMain{
 public static void main(String[]args)throws Exception{Path fixtures=Path.of(args[0]),output=Path.of(args[1]);ObjectMapper json=new ObjectMapper();GameRuleCore rules=new GameRuleCore();Map<String,Integer>captured=new LinkedHashMap<>();for(String k:List.of("ORDINARY_LOSS","ORDINARY_WIN","MYSTERY_BOX","FREE_TRIGGER","FREE_TERMINAL_SNAPSHOT"))captured.put(k,0);int exact=0,total=0;try(var paths=Files.walk(fixtures.resolve("spin"))){for(Path p:(Iterable<Path>)paths.filter(x->x.toString().endsWith(".response.json"))::iterator){JsonNode d=json.readTree(p.toFile()).path("data"),props=d.path("props");int[]board=new int[15];for(int i=0;i<15;i++)board[i]=props.path("prop").get(i).asInt();var wins=rules.evaluate(board);boolean match=wins.size()==props.path("win_arr").size();long units=0;for(int i=0;i<wins.size()&&match;i++){var w=wins.get(i);JsonNode a=props.path("win_arr").get(i);match=a.path("line").asInt()==w.line()&&a.path("num").asInt()==w.num()&&a.path("odd").asInt()==w.odd()&&a.path("wp").asInt()==w.wp();units+=w.odd();}match&=Math.abs(props.path("tw").asDouble()-units*.2)<.00001;if(match)exact++;total++;String kind;if(d.path("type").asInt()==2)kind="FREE_TERMINAL_SNAPSHOT";else if(d.path("frees").path("st").asInt()>0)kind="FREE_TRIGGER";else if(d.path("spe_pos").size()>0)kind="MYSTERY_BOX";else kind=props.path("tw").asDouble()>0?"ORDINARY_WIN":"ORDINARY_LOSS";captured.merge(kind,1,Integer::sum);}}
  int generatedTotal=10000;Map<GameRuleCore.RoundKind,Integer>generated=new LinkedHashMap<>();Map<GameRuleCore.RoundKind,Long>units=new LinkedHashMap<>();for(var k:GameRuleCore.RoundKind.values()){generated.put(k,0);units.put(k,0L);}RoundFactory factory=new RoundFactory(rules);SecureRandom random=new SecureRandom();for(int i=0;i<generatedTotal;i++){int draw=random.nextInt(1428);var kind=draw<1189?GameRuleCore.RoundKind.ORDINARY_LOSS:draw<1290?GameRuleCore.RoundKind.ORDINARY_WIN:draw<1390?GameRuleCore.RoundKind.MYSTERY_BOX:GameRuleCore.RoundKind.FREE_STICKY_SYMBOLS;var round=factory.generate(kind);rules.validate(round);generated.merge(kind,1,Integer::sum);units.merge(kind,new ResultUtil(rules).totalUnits(round),Long::sum);}
  Map<String,Object>report=new LinkedHashMap<>();report.put("schemaVersion",1);report.put("gameId",2110);report.put("rulesHash",GameRuleCore.RULES_HASH);report.put("capturedResponses",total);report.put("capturedRuleExactMatches",exact);report.put("capturedClassification",captured);report.put("paidStartDenominator",1428);report.put("empiricalWeights",Map.of("ORDINARY_LOSS",1189.0/1428,"ORDINARY_WIN",101.0/1428,"MYSTERY_BOX",100.0/1428,"FREE_STICKY_SYMBOLS",38.0/1428));report.put("completeFreeRoundEvidence",Map.of("count",1,"target",30,"status","SAMPLE_INSUFFICIENT"));report.put("generatedSamples",generatedTotal);Map<String,Object>g=new LinkedHashMap<>();for(var k:GameRuleCore.RoundKind.values())g.put(k.name(),Map.of("count",generated.get(k),"share",generated.get(k)/(double)generatedTotal,"averagePayoutUnits",generated.get(k)==0?0:units.get(k)/(double)generated.get(k)));report.put("generatedDistribution",g);report.put("verdict",exact==total?"RULE_ORACLE_EXACT_AND_GENERATION_INVARIANTS_PASS":"FAIL");Files.createDirectories(output.getParent());json.writerWithDefaultPrettyPrinter().writeValue(output.toFile(),report);System.out.println(output.toAbsolutePath());}
}
